ROOT=Path(__file__).resolve().parents[1]
A=[]; EXTRA=[]; OPS=[]
N='CurrDateTime()'; U='GetUserId()'
def p(n,t,mandatory=True):return {'name':n,'type':t,'mandatory':mandatory}
def ident(e):return e+' Identifier'
def lit(s):return '"'+s.replace('"','""')+'"'
def setv(**d):return {'assign':d}
def req(c,msg='Operação inválida',ex='HireValidation'):return {'if':c,'then':[{'raise':ex,'message':lit(msg)}]}
def call(n,alias,**args):return {'call':n,'as':alias,'args':args}
def get(e,alias,where,max=1,sort=None,start=None):
 d={'get':e,'as':alias,'where':where,'max':max}
 if sort:d['sort']=sort
 if start is not None:d['start']=start
 return d
def current(alias,e):return alias+'.List.Current.'+e
def read(e,alias,idexpr):return [get(e,alias,e+'.Id = '+idexpr),req(alias+'.List.Empty','Registro não encontrado','HireNotFound')]
def lock(e,idexpr,alias='LockRow'):return call('Get'+e+'ForUpdate',alias,Id=idexpr)
def save(e,var='R',alias='SaveRow'):return {'update':e,'record':var,'as':alias}
def create(e,var='R',alias='CreateRow'):return {'create':e,'record':var,'as':alias}
def auth(org,permission='Recruit',alias='Authorize'):return call('Access_RequireOrganization',alias,OrganizationId=org,PermissionCode=lit(permission))
def audit(org,e,idexpr,op):return call('Audit_Record','Audit',OrganizationId=org,Operation=lit(op),EntityType=lit(e),RecordIdentifier='LongIntegerToText('+idexpr+')')
def action(name,inputs=(),outputs=(),vars=(),steps=(),public=True,description=None):
 d={'name':name,'kind':'server','public':public,'description':description or 'Hire: '+name+'. Autorizações e invariantes verificadas no servidor.','inputs':list(inputs),'outputs':list(outputs),'vars':list(vars),'steps':list(steps)}
 A.append(d);return d

