# Generic implementation macros compile to explicit entity-specific, field-whitelisted actions.
SCHEMA={e['name']:e for e in data.ENTITIES}
def scope(en,idexpr,permission='Recruit'):
 return [call('Scope_'+en,'ResolveScope',RecordId=idexpr),auth('ResolveScope.OrganizationId',permission)]
def rev(en,idexpr='RecordId',alias='ReadRecord'):
 return [lock(en,idexpr)]+read(en,alias,idexpr)+[setv(R=current(alias,en)),call('Concurrency_RequireRevision','CheckRevision',ActualRevision='R.Revision',ExpectedRevision='ExpectedRevision')]
def finish(en,name,orgexpr='ResolveScope.OrganizationId'):
 return [setv(**{'R.UpdatedAt':N,'R.UpdatedByUserId':U,'R.Revision':'R.Revision + 1'}),save(en),audit(orgexpr,en,'R.Id',name),setv(NewRevision='R.Revision')]
def relation_checks(en,var='Input'):
 steps=[]
 for x in SCHEMA[en]['attributes']:
  typ=x['type'];field=x['name']
  if not typ.endswith(' Identifier') or typ[:-11] not in PARENTS or field=='OrganizationId':continue
  target=typ[:-11];al='Scope'+field
  check=[call('Scope_'+target,al,RecordId=var+'.'+field),req(al+'.OrganizationId <> OrganizationId','Referência fora da empresa','HireAccessDenied')]
  steps += check if x['mandatory'] else [{'if':var+'.'+field+' <> NullIdentifier()','then':check}]
 return steps

def upsert(name,en,fields,permission='Manage',extra=()):
 inputs=[p('OrganizationId',ident('Organization')),p('Input',en),p('ExpectedRevision','Integer')]
 steps=[auth('OrganizationId',permission),{'if':'Input.Id <> NullIdentifier()','then':[call('Scope_'+en,'ExistingScope',RecordId='Input.Id'),req('ExistingScope.OrganizationId <> OrganizationId','Registro de outra empresa','HireAccessDenied')]+rev(en,'Input.Id'),'else':[req('ExpectedRevision <> 0','Revisão inicial deve ser zero'),setv(**{'R.CreatedAt':N,'R.CreatedByUserId':U,'R.Revision':'0'})]}]
 steps+=relation_checks(en)
 for field in fields:
  x=next(x for x in SCHEMA[en]['attributes'] if x['name']==field)
  if x['mandatory'] and x['type']=='Text':steps.append(req('Length(Trim(Input.'+field+')) = 0',field+' obrigatório'))
 steps+=list(extra)+[setv(**{'R.'+f:'Input.'+f for f in fields})]
 if PARENTS[en]=='OrganizationId':steps.append(setv(**{'R.OrganizationId':'OrganizationId'}))
 steps += [setv(**{'R.UpdatedAt':N,'R.UpdatedByUserId':U,'R.Revision':'R.Revision + 1'}),{'save':en,'record':'R','as':'SaveRow'},setv(RecordId='SaveRow.Id',NewRevision='R.Revision'),audit('OrganizationId',en,'RecordId',name)]
 action(name,inputs,[p('RecordId',ident(en)),p('NewRevision','Integer')],[p('R',en)],steps)

