# Read endpoints: no arbitrary sort/SQL, bounded pages, full records restricted to recruiting staff.
def query(name,en,orgparent=None,where='True',extra_inputs=(),sortfield='Id'):
 ins=[p('OrganizationId',ident('Organization')),p('StartIndex','Integer'),p('PageSize','Integer')]+list(extra_inputs)
 base=auth('OrganizationId')
 if PARENTS[en]=='OrganizationId':
  predicate=en+'.OrganizationId = OrganizationId and ('+where+')'
  steps=[base,req('StartIndex < 0 or PageSize < 1 or PageSize > 100','Paginação inválida'),get(en,'Rows',predicate,'PageSize',[en+'.'+sortfield,'Ascending'],'StartIndex')]
 else:
  # Explicit SQL join paths to the organization root are resolved from the fixed data model.
  clauses=[];joins=[];cursor=en
  seen=set()
  while PARENTS[cursor] != 'OrganizationId':
   if cursor in seen:raise ValueError(cursor)
   seen.add(cursor);field,parent=PARENTS[cursor];joins.append(' INNER JOIN {'+parent+'} ON {'+cursor+'}.['+field+'] = {'+parent+'}.[Id]');cursor=parent
  statement='SELECT {'+en+'}.* FROM {'+en+'}'+''.join(joins)+' WHERE {'+cursor+'}.[OrganizationId] = @Org ORDER BY {'+en+'}.['+sortfield+'] OFFSET @Start ROWS FETCH NEXT @Size ROWS ONLY'
  steps=[base,req('StartIndex < 0 or PageSize < 1 or PageSize > 100','Paginação inválida'),{'get':en,'sql':True,'as':'Rows','statement':statement,'params':{'Org':{'type':ident('Organization'),'value':'OrganizationId'},'Start':{'type':'Integer','value':'StartIndex'},'Size':{'type':'Integer','value':'PageSize'}},'max':'PageSize'}]
 steps += [{'foreach':'Rows.List','as':'CopyRows','do':[setv(Row=current('Rows',en)),call('ListAppend','AppendRow',List='Items',Element='Row')]}]
 action(name,ins,[p('Items',en+' List')],[p('Row',en)],steps)
